from pathlib import Path
css=Path('/home/ubuntu/tech-shift/client/src/index.css')
s=css.read_text()
s += '''

/* Final curriculum modules */
.paradigm-compare { display: grid; grid-template-columns: 1fr auto 1.5fr; gap: 22px; align-items: center; padding: 28px; border: 1px solid var(--border-color); background: var(--bg-surface); }.paradigm-compare div { display: grid; gap: 12px; }.paradigm-compare .mono, .tree-label { color: var(--accent-cyan); font-size: 11px; }.paradigm-compare strong { color: var(--text-primary); font: 500 24px/1.2 var(--display); }.paradigm-compare > svg { color: var(--accent-cyan); }.stack-tree { display: grid; grid-template-columns: repeat(3,1fr); gap: 10px; margin-top: 12px; }.stack-tree > div { min-height: 130px; display: grid; align-content: space-between; padding: 18px; border: 1px solid var(--border-color); background: var(--bg-surface-elevated); }.stack-tree strong { color: var(--text-primary); font: 500 19px/1.15 var(--display); }.action-matrix { display: flex; flex-wrap: wrap; gap: 10px; max-width: 900px; }.action-matrix span { padding: 14px 16px; border: 1px solid var(--accent-cyan); background: var(--accent-cyan-bg, rgba(2,132,199,.08)); color: var(--accent-cyan); font: 12px var(--mono); animation: action-pop .5s var(--ease-out) both; animation-delay: calc(var(--i) * 40ms); }.human-ai-grid { display: grid; grid-template-columns: 1fr 1fr; gap: 12px; margin-top: 24px; }.human-ai-grid article { padding: 22px; border: 1px solid var(--border-color); background: var(--bg-surface); }.human-ai-grid p { margin: 18px 0 0; color: var(--text-secondary); font-size: 18px; line-height: 1.75; }.future-map-grid { display: grid; grid-template-columns: repeat(3,1fr); gap: 12px; }.future-map-card { position: relative; min-height: 225px; padding: 20px; border: 1px solid var(--border-color); background: var(--bg-surface); }.future-map-card > span:nth-child(2) { float: right; color: var(--text-muted); font-size: 10px; }.future-map-card h3 { margin: 36px 0 10px; color: var(--text-primary); font: 500 22px/1 var(--display); }.future-map-card p { color: var(--text-secondary); font-size: 18px; line-height: 1.65; }.execution-loop { display: flex; flex-wrap: wrap; align-items: center; gap: 12px; margin-top: 25px; padding: 20px; border: 1px solid var(--accent-violet); background: var(--accent-violet-bg, rgba(168,85,247,.06)); }.execution-loop span { display: flex; align-items: center; gap: 8px; color: var(--text-primary); font: 12px var(--mono); }.execution-loop b { color: var(--accent-violet); }.execution-loop svg { color: var(--accent-violet); }.programming-ladder { display: grid; grid-template-columns: repeat(3,1fr); gap: 12px; }.programming-ladder article { min-height: 235px; padding: 22px; border: 1px solid var(--border-color); background: var(--bg-surface); }.programming-ladder article > span:first-child { float: right; color: var(--text-muted); font-size: 10px; }.programming-ladder h3 { margin: 32px 0 10px; color: var(--text-primary); font: 500 24px var(--display); }.programming-ladder p { color: var(--text-secondary); font-size: 18px; line-height: 1.65; }.shutdown-lines { display: grid; gap: 6px; margin: 24px 0; }.shutdown-lines span { display: block; padding: 14px 18px; border-left: 2px solid var(--accent-red); background: rgba(239,68,68,.05); color: var(--accent-red); font: 600 clamp(22px,3vw,36px)/1 var(--mono); letter-spacing: -.05em; animation: shutdown-in .55s var(--ease-out) both; animation-delay: calc(var(--i) * 90ms); }.first-shock { max-width: 720px; padding: 22px; border: 1px solid var(--border-color); background: var(--bg-surface); }.first-shock span { color: var(--accent-red); font-size: 10px; }.first-shock p { margin: 12px 0 0; color: var(--text-secondary); font-size: 18px; line-height: 1.75; }.sector-grid { display: grid; grid-template-columns: repeat(4,1fr); gap: 10px; }.sector-card { min-height: 250px; padding: 20px; border: 1px solid rgba(239,68,68,.25); background: var(--bg-surface); }.sector-card > span { color: var(--accent-red); font-size: 10px; }.sector-card h3 { margin: 35px 0 10px; color: var(--text-primary); font: 500 21px/1.05 var(--display); }.sector-card p { color: var(--text-secondary); font-size: 17px; line-height: 1.65; }.cascade-chain { display: flex; flex-wrap: wrap; align-items: center; gap: 9px; margin-top: 24px; padding: 18px; border: 1px solid var(--border-color); background: var(--bg-surface); }.cascade-chain span { display: flex; align-items: center; gap: 9px; color: var(--accent-red); font: 11px var(--mono); }.cascade-chain svg { color: var(--text-muted); }.manual-ladder { display: grid; gap: 8px; }.manual-ladder > div { display: grid; grid-template-columns: 1fr 25px 1fr; align-items: center; gap: 15px; padding: 17px 20px; border: 1px solid var(--border-color); background: var(--bg-surface); }.manual-ladder strong, .manual-ladder span { color: var(--text-primary); font-size: 18px; }.manual-ladder svg { color: var(--accent-red); }.recovery-steps { display: grid; grid-template-columns: repeat(7,1fr); gap: 6px; }.recovery-steps span { min-height: 120px; display: grid; align-content: space-between; padding: 13px; border: 1px solid rgba(199,255,74,.3); background: var(--bg-surface); color: var(--text-primary); font-size: 15px; }.recovery-steps b { color: var(--lime); font: 10px var(--mono); }
@keyframes action-pop { from { opacity: 0; transform: translateY(10px); } to { opacity: 1; transform: none; } } @keyframes shutdown-in { from { opacity: 0; transform: translateX(-18px); } to { opacity: 1; transform: none; } }
@media (max-width: 900px) { .future-map-grid, .sector-grid { grid-template-columns: repeat(2,1fr); }.recovery-steps { grid-template-columns: repeat(4,1fr); }.stack-tree { grid-template-columns: 1fr; }.paradigm-compare { grid-template-columns: 1fr; }.paradigm-compare > svg { transform: rotate(90deg); justify-self: center; }.programming-ladder { grid-template-columns: 1fr; } }
@media (max-width: 620px) { .human-ai-grid, .future-map-grid, .sector-grid { grid-template-columns: 1fr; }.execution-loop { align-items: flex-start; flex-direction: column; }.recovery-steps { grid-template-columns: repeat(2,1fr); }.manual-ladder > div { grid-template-columns: 1fr; gap: 8px; }.manual-ladder svg { transform: rotate(90deg); }.shutdown-lines span { font-size: 22px; } }
'''
css.write_text(s)
